"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

import calendar
import re
from dataclasses import dataclass
from datetime import datetime

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"

_IMF_FIXDATE = re.compile(
    r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), "
    r"([0-9]{2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)
_MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
_DIGITS = re.compile(r"[0-9]+")


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _is_digits(text: str) -> bool:
    return _DIGITS.fullmatch(text) is not None


def _split_commas(text: str) -> list[str]:
    parts: list[str] = []
    buf: list[str] = []
    in_quotes = False
    for ch in text:
        if ch == '"':
            in_quotes = not in_quotes
        elif ch == "," and not in_quotes:
            parts.append("".join(buf))
            buf = []
            continue
        buf.append(ch)
    parts.append("".join(buf))
    return parts


def _unquote(value: str) -> str:
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        return value[1:-1]
    return value


def _directive_is_valid(name: str, value: str | None) -> bool:
    if name == "max-stale":
        return value is None or _is_digits(value)
    if name in ("max-age", "s-maxage", "min-fresh"):
        return value is not None and _is_digits(value)
    return True


def _parse_cache_control(header: str | None) -> dict[str, str | None]:
    if header is None:
        return {}
    directives: dict[str, str | None] = {}
    for element in _split_commas(header):
        element = element.strip()
        if not element:
            continue
        name, has_value, value = element.partition("=")
        name = name.strip().lower()
        parsed_value = _unquote(value.strip()) if has_value else None
        if _directive_is_valid(name, parsed_value):
            directives[name] = parsed_value
    return directives


def _parse_http_date(header: str) -> int:
    match = _IMF_FIXDATE.fullmatch(header.strip())
    if match is None:
        raise HeaderError(f"not an IMF-fixdate: {header!r}")
    day, month, year, hour, minute, second = match.groups()
    try:
        moment = datetime(
            int(year),
            _MONTHS.index(month) + 1,
            int(day),
            int(hour),
            int(minute),
            int(second),
        )
    except ValueError as exc:
        raise HeaderError(f"not a real date and time: {header!r}") from exc
    return calendar.timegm(moment.timetuple())


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    resp = {k.lower(): v for k, v in response_headers.items()}
    req = {k.lower(): v for k, v in request_headers.items()}
    resp_cc = _parse_cache_control(resp.get("cache-control"))
    req_cc = _parse_cache_control(req.get("cache-control"))

    date_header = resp.get("date")
    date = response_time if date_header is None else _parse_http_date(date_header)
    expires_header = resp.get("expires")
    expires = None if expires_header is None else _parse_http_date(expires_header)
    last_modified_header = resp.get("last-modified")
    last_modified = (
        None if last_modified_header is None else _parse_http_date(last_modified_header)
    )

    age_header = resp.get("age", "").strip()
    age = int(age_header) if _is_digits(age_header) else 0

    if "s-maxage" in resp_cc:
        lifetime = int(resp_cc["s-maxage"])
    elif "max-age" in resp_cc:
        lifetime = int(resp_cc["max-age"])
    elif expires is not None:
        lifetime = max(0, expires - date)
    elif last_modified is not None:
        lifetime = max(0, (date - last_modified) // 10)
    else:
        lifetime = 0

    if "max-age" in req_cc:
        lifetime = min(lifetime, int(req_cc["max-age"]))

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = age + response_delay
    initial_age = max(apparent_age, corrected_age)
    current_age = initial_age + (now - response_time)

    if any(d in resp_cc for d in ("no-store", "no-cache", "must-revalidate")) or "no-cache" in req_cc:
        verdict = MUST_REVALIDATE
    else:
        min_fresh = int(req_cc["min-fresh"]) if "min-fresh" in req_cc else 0
        if lifetime > current_age + min_fresh:
            verdict = FRESH
        elif "max-stale" in req_cc:
            allowed = req_cc["max-stale"]
            if allowed is None or current_age - lifetime <= int(allowed):
                verdict = FRESH
            else:
                verdict = STALE
        else:
            verdict = STALE

    return Result(verdict, current_age, lifetime)
